mapper.select:
select sp.staff_account as staffAccount, sp.package_id as packageId, p.package_name as packageName, p.package_price as packagePrice, p.unit_text as unitText from sys_staff_package sp join homemaking_package p on p.id = sp.package_id where p.is_deleted = 0 and sp.staff_account in
#{account}
order by sp.staff_account asc, p.id asc
